#!/usr/bin/env bash\nset -euo pipefail\n\nROOT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"\nDIST_DIR="${1:-$ROOT_DIR/dist}"\nRELEASE_TARGET="${2:-}"\nEXPECTED_ARCH="$(dpkg --print-architecture)"\nWORK_DIR="$(mktemp -d)"\ntrap 'rm -rf "$WORK_DIR"' EXIT\n\nif [[ -n "$RELEASE_TARGET" && ! "$RELEASE_TARGET" =~ ^[a-z0-9][a-z0-9.-]*$ ]]; then\n    printf 'Invalid release target: %s\n' "$RELEASE_TARGET" >&2\n    exit 1\nfi\n\nshopt -s nullglob\n\nfor package_name in better-manager better-monitor; do\n    if [[ -n "$RELEASE_TARGET" ]]; then\n        package_paths=("$DIST_DIR/${package_name}_"*"_${RELEASE_TARGET}_${EXPECTED_ARCH}.deb")\n    else\n        package_paths=("$DIST_DIR/${package_name}_"*.deb)\n    fi\n    if [[ ${#package_paths[@]} -ne 1 ]]; then\n        printf 'Expected exactly one target-specific package for %s\n' "$package_name" >&2\n        exit 1\n    fi\n    deb_path="${package_paths[0]}"\n    checksum_path="$deb_path.sha256"\n    extract_dir="$WORK_DIR/$package_name"\n\n    if [[ ! -f "$deb_path" || ! -f "$checksum_path" ]]; then\n        printf 'Missing package or checksum: %s\n' "$package_name" >&2\n        exit 1\n    fi\n\n    (\n        cd "$DIST_DIR"\n        sha256sum --check "$(basename "$checksum_path")"\n    )\n\n    actual_name="$(dpkg-deb -f "$deb_path" Package)"\n    actual_arch="$(dpkg-deb -f "$deb_path" Architecture)"\n    depends="$(dpkg-deb -f "$deb_path" Depends)"\n\n    [[ "$actual_name" == "$package_name" ]] || {\n        printf 'Unexpected package name: %s\n' "$actual_name" >&2\n        exit 1\n    }\n    [[ "$actual_arch" == "$EXPECTED_ARCH" ]] || {\n        printf 'Unexpected architecture for %s: %s\n' "$package_name" "$actual_arch" >&2\n        exit 1\n    }\n\n    if [[ "$depends" =~ (^|,)[[:space:]]*[^,]*-dev([[:space:]]|,|$) ]]; then\n        printf 'Build-time development package leaked into %s: %s\n' "$package_name" "$depends" >&2\n        exit 1\n    fi\n\n    for required_dependency in \\n        libfontconfig1 \\n        libxcb1 \\n        libxkbcommon0 \\n        libxkbcommon-x11-0 \\n        libwayland-client0 \\n        libwayland-egl1 \\n        libwayland-cursor0; do\n        if ! printf '%s\n' "$depends" | grep -Eq "(^|,)[[:space:]]*${required_dependency}([[:space:]]|,|$)"; then\n            printf 'Missing runtime dependency for %s: %s\n' "$package_name" "$required_dependency" >&2\n            exit 1\n        fi\n    done\n\n    dpkg-deb --extract "$deb_path" "$extract_dir"\n    binary_path="$extract_dir/usr/bin/$package_name"\n    [[ -x "$binary_path" ]] || {\n        printf 'Missing executable in %s\n' "$package_name" >&2\n        exit 1\n    }\n\n    notice_dir="$extract_dir/usr/share/doc/$package_name"\n    [[ -s "$notice_dir/copyright" ]] || {\n        printf 'Missing project license notice in %s\n' "$package_name" >&2\n        exit 1\n    }\n    [[ -s "$notice_dir/THIRD-PARTY-LICENSES.md" ]] || {\n        printf 'Missing third-party license notice inventory in %s\n' "$package_name" >&2\n        exit 1\n    }\n    cmp "$ROOT_DIR/LICENSE" "$notice_dir/copyright" >/dev/null || {\n        printf 'Project license notice does not match repository LICENSE in %s\n' "$package_name" >&2\n        exit 1\n    }\n    grep -q '^# Third-Party License Notices$' "$notice_dir/THIRD-PARTY-LICENSES.md" || {\n        printf 'Invalid third-party license notice inventory in %s\n' "$package_name" >&2\n        exit 1\n    }\n\n    if ldd "$binary_path" | grep -q 'not found'; then\n        printf 'Unresolved dynamic library in %s\n' "$package_name" >&2\n        exit 1\n    fi\n\n    printf 'Verified %s (%s)\n' "$deb_path" "$actual_arch"\ndone\n\n# The privileged service is packaged differently from the desktop applications:\n# it has no graphics dependencies, its binary lives in /usr/libexec because a\n# person never starts it, and it is the only package that ships the policy and\n# transport files that decide who may change this machine.\ndaemon_name="better-manager-daemon"\nif [[ -n "$RELEASE_TARGET" ]]; then\n    daemon_paths=("$DIST_DIR/${daemon_name}_"*"_${RELEASE_TARGET}_${EXPECTED_ARCH}.deb")\nelse\n    daemon_paths=("$DIST_DIR/${daemon_name}_"*.deb)\nfi\nif [[ ${#daemon_paths[@]} -ne 1 ]]; then\n    printf 'Expected exactly one target-specific package for %s\n' "$daemon_name" >&2\n    exit 1\nfi\ndaemon_path="${daemon_paths[0]}"\ndaemon_extract="$WORK_DIR/$daemon_name"\n\nif [[ ! -f "$daemon_path" || ! -f "$daemon_path.sha256" ]]; then\n    printf 'Missing package or checksum: %s\n' "$daemon_name" >&2\n    exit 1\nfi\n(\n    cd "$DIST_DIR"\n    sha256sum --check "$(basename "$daemon_path.sha256")"\n)\n\ndaemon_depends="$(dpkg-deb -f "$daemon_path" Depends)"\nif [[ "$daemon_depends" =~ (^|,)[[:space:]]*[^,]*-dev([[:space:]]|,|$) ]]; then\n    printf 'Build-time development package leaked into %s: %s\n' "$daemon_name" "$daemon_depends" >&2\n    exit 1\nfi\nfor required_dependency in dbus apt dpkg; do\n    if ! printf '%s\n' "$daemon_depends" | grep -Eq "(^|,)[[:space:]]*${required_dependency}([[:space:]]|,|$)"; then\n        printf 'Missing runtime dependency for %s: %s\n' "$daemon_name" "$required_dependency" >&2\n        exit 1\n    fi\ndone\nif printf '%s\n' "$daemon_depends" | grep -Eq 'libwayland|libfontconfig|libxkbcommon'; then\n    printf 'Graphics dependency leaked into the privileged service: %s\n' "$daemon_depends" >&2\n    exit 1\nfi\n\ndpkg-deb --extract "$daemon_path" "$daemon_extract"\nfor required_file in \\n    usr/libexec/better-manager-daemon \\n    usr/lib/systemd/system/better-manager-daemon.service \\n    usr/share/dbus-1/system-services/org.betteros.Manager1.service \\n    usr/share/dbus-1/system-services/org.betteros.Monitor1.service \\n    usr/share/dbus-1/system.d/org.betteros.Manager1.conf \\n    usr/share/dbus-1/system.d/org.betteros.Monitor1.conf \\n    usr/share/polkit-1/actions/org.betteros.manager.policy \\n    usr/share/doc/better-manager-daemon/copyright \\n    usr/share/doc/better-manager-daemon/THIRD-PARTY-LICENSES.md; do\n    if [[ ! -s "$daemon_extract/$required_file" ]]; then\n        printf 'Missing %s in %s\n' "$required_file" "$daemon_name" >&2\n        exit 1\n    fi\ndone\n[[ -x "$daemon_extract/usr/libexec/better-manager-daemon" ]] || {\n    printf 'The privileged service binary is not executable\n' >&2\n    exit 1\n}\n\n# The unit must stay D-Bus activated. An [Install] section would mean it runs\n# at boot, which is not what a package manager should do.\nif grep -q '^\[Install\]' "$daemon_extract/usr/lib/systemd/system/better-manager-daemon.service"; then\n    printf 'The privileged service must not be enabled at boot\n' >&2\n    exit 1\nfi\ngrep -q '^BusName=org.betteros.Manager1$' \\n    "$daemon_extract/usr/lib/systemd/system/better-manager-daemon.service" || {\n    printf 'The privileged service unit does not claim the expected bus name\n' >&2\n    exit 1\n}\ngrep -q 'org.betteros.manager.apply-transaction' \\n    "$daemon_extract/usr/share/polkit-1/actions/org.betteros.manager.policy" || {\n    printf 'The polkit policy does not declare the apply action\n' >&2\n    exit 1\n}\ngrep -q 'org.betteros.monitor.read-memory-devices' \\n    "$daemon_extract/usr/share/polkit-1/actions/org.betteros.manager.policy" || {\n    printf 'The polkit policy does not declare the monitor DMI action\n' >&2\n    exit 1\n}\n\nif ldd "$daemon_extract/usr/libexec/better-manager-daemon" | grep -q 'not found'; then\n    printf 'Unresolved dynamic library in %s\n' "$daemon_name" >&2\n    exit 1\nfi\n\nprintf 'Verified %s (%s)\n' "$daemon_path" "$EXPECTED_ARCH"\n